import type { CategoryId, Faq } from "./types"

/** One row of a category's "Which one should I use?" table. */
export type PickerRow = {
  /** What the reader is trying to do, in their words. */
  need: string
  /** Registry name of the component that answers it. */
  use: string
  /** Why this one, in a few words. */
  note: string
}

export type Category = {
  id: CategoryId
  /** Short label for chips and nav. */
  label: string
  /** The page H1: the phrase people search. (tools/build-registry.mjs reads id, label and h1 in this order.) */
  h1: string
  /** <title>, before the site suffix. Under 55 characters. */
  title: string
  /** Meta description, 140-160 characters. */
  description: string
  /** One line for the /components index card. */
  blurb: string
  /** Two short paragraphs: what is in the category, then how to choose. */
  intro: [string, string]
  /** Need -> component rows, using only components in this category or close by. */
  picker: PickerRow[]
  faq: Faq[]
  related: CategoryId[]
  /** Gallery pages that show these components wired up. */
  galleries: string[]
  /** A guide that goes deeper, if one exists. */
  guide?: string
}

